/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isNonNegativeInteger = require( '@stdlib/assert/is-nonnegative-integer' ).isPrimitive;
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Set plotArea width.
* Note: plot area is the spaces where the specific plot draw there plots this readonly property give row and column coordinates of this area.
*
* @private
* @param {NonNegativeInteger} value - width
* @throws {TypeError} must be a non negative number
* @throws {Error} must be a valid glyph name
*/
function set( value ) {
	if ( !isNonNegativeInteger( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a non negative number. Value: `%s`.', 'width', value ) );
	}
	if ( this._plotAreaWidth !== value ) {
		this._plotAreaWidth = value;
		if ( !this._quite ) {
			// Change in plot area require the re initialization of buffer
			this.emit( 'initialize' );

			this.emit( 'change' );
		}
	}
}


// EXPORTS //

module.exports = set;
